class RsiState(Enum):
    CONNECTED = "connected"
    LOGGED_IN = "logged_in"
    UBOOT_DETECTED = "uboot_detected"
    LOGIN_POSSIBLE = "login_possible"
    REBOOT_DETECTED = "reboot_detected"


class UartConnector:
    def __init__(self, rsi):
        self._rsi = rsi
        self._thread = None
        self._stop_event = threading.Event()
        self.parameters = None
        self.rom_snapshot_dir = None
        self._rom = "/mnt/runtime/"
        self._rom_user_snapshot_dir = "snapshot/"
        self._rom_auto_snapshot_dir = "auto_snapshot/"
        self.snapshot_succeed_msg = "AaSysComUserDeregister succeed!"
        self.user_snapshot_and_debug_files_for_download = set()
        self._critical_active_faults = defaultdict(set)
        self._normal_active_faults = defaultdict(list)
        self.tstamp_format = "%H%M%S_%Y-%m-%d"
        self.as_rfsw = "sudo -u rfsw sh -c "
        self.ssh_handler = None
        self.logger = None
        self.alias = None
        self.user_snapshot_ongoing = False
        self.auto_snapshot_ongoing = False
        self.auto_snapshot_start_time = None

    def connect_new_rmod(self, ru: RU, alias: str, use_init_credentials: bool = False, **kwargs):
        """Setups new instance of radio connection for each UART. It gets data from RU class
        and saves it to RmodConfiguration object which supports both legacy and new RU objects creation.
        Lastly it starts new thread for given radio. If there is second port saved in RU class it will also create
        second connection for second UART port.
        After connection is opened runtime RMOD log (serial output) collection will be started.
        Args:
            ru (RU): Radio connection configuration from RU init file.
            alias (str): Name under which connection will be created.
            use_init_credentials (bool): If set to True, then initial credentials from RU config will be used.
                Defaults to False.
            kwargs (dict): Additional parameters for RSI, PC host connection setup.
        """
        self.logger = self.parameters.logger
        fh_interface = self.parameters.ru_config.fh_interface
        rsi_aliases = self._rsi.setup_rmod_connection_from_ru_config(
            ru, alias, fh_interface=fh_interface, use_init_credentials=use_init_credentials, **kwargs
        )
        self.alias = rsi_aliases[0]
        self.parameters.is_connected = True
        if self._is_uart_connection_established():
            self._create_file_preserving_flags_if_logged_in()
            self._remove_previous_snapshot_files()
        else:
            self.parameters.is_connected = False
        if use_init_credentials:
            self.parameters.ru_config.password = self.parameters.ru_config.init_password
            self.parameters.ru_config.username = self.parameters.ru_config.init_username

    def send_command(self, cmd: str, as_rfsw: bool = True):
        """Sends given command without expecting output.
        Args:
            cmd (str): Command to send.
            as_rfsw (bool): If set to True, then command will be executed as rfsw user. Defaults to True.
        Returns:
            None
        """
        self._send_command(cmd=cmd, as_rfsw=as_rfsw)

    def execute_command(
        self, cmd: str, elevated=False, wait_time: int = 30, write_output_to_logs: bool = True, as_rfsw: bool = True
    ):
        """Sends given command and expects the output.
        Args:
            cmd (str): Command to send.
            elevated (bool): try to run command with elevated permissions. Defaults to False.
            wait_time (int): Wait time to receive data. Defaults to 30.
            write_output_to_logs (bool): By default command output is saved in the log file.
                It may be skipped when output is long, and it is not necessary to have them duplicated with RSI lib.
                Defaults to True.
            as_rfsw (bool): If set to True, then command will be executed as rfsw user. Defaults to True.
        Returns:
            str: Received data or empty sting if data is None.
        """
        return self._execute_command(
            cmd=cmd,
            elevated=elevated,
            wait_time=wait_time,
            write_output_to_logs=write_output_to_logs,
            with_rsi=False,
            as_rfsw=as_rfsw,
        )

    def reset_rmod(self, wait_time: int = 100):
        """Reboots RMOD and waits for given time (until it is back).
        Args:
            wait_time (int): Wait time between sending the command and returning state. Defaults to 100.
        Returns:
            None
        """
        self._wait_for_snapshot_completion(user_snapshot=False)
        self._reset_rmod(wait_time)

    def take_snapshot(
        self,
        target_path_on_vm: str = None,
        reset_rmod: bool = False,
        stop_and_fix: bool = False,
        skip_downloading: bool = False,
        timeout: int = 180,
        proxy_vm_address=None,
        proxy_vm_username=None,
    ):
        """Takes snapshot from RMOD and saves it on VM connected to the serial console board.
        Additional debug logs from RMOD are collected and saved to the debug log file.
        Args:
            target_path_on_vm (str): Target directory to download a snapshot file. If None, then it will be saved to
            RMOD ROM only without downloading
            reset_rmod (bool): reset command will be sent to the RMOD if set to True, for example when FID:10 detected,
                Defaults to False.
            stop_and_fix (bool): The master flag to do not reset RMOD even if asked, for example determined by FID:10.
                Defaults to False.
            skip_downloading (bool): If set to True, then file will be created in RMOD's ROM and not downloaded to VM.
                It is useful when snapshot is created in case of connection problems and can be moved after recovery.
            timeout (int): time in seconds to execute snapshot command (downloading time is not counted).
                Defaults to 180.
            proxy_vm_address (str): Proxy VM address for SSH handler.
            proxy_vm_username (str): Proxy VM username for SSH handler.
        Returns:
            bool: True only if snapshot created in RMODs ROM and copied to VM, False otherwise
        """
        if not self._wait_for_snapshot_completion(user_snapshot=False):
            return False
        self.user_snapshot_ongoing = True
        snapshot_status = self._take_snapshot(
            reset_rmod=reset_rmod,
            skip_downloading=skip_downloading,
            stop_and_fix=stop_and_fix,
            target_path_on_vm=target_path_on_vm,
            timeout=timeout,
            proxy_vm_address=proxy_vm_address,
            proxy_vm_username=proxy_vm_username,
        )
        self.user_snapshot_ongoing = False
        return snapshot_status

    def download_snapshot(
        self, target_path_on_vm: str = None, proxy_vm_address: str = None, proxy_vm_username: str = None
    ):
        """Downloads snapshot from RMOD and saves it on VM connected to the serial console board.
        Args:
            target_path_on_vm (str): Target directory to download a snapshot file. If None, then it will be saved to
            the main log directory
            proxy_vm_address (str): Proxy VM address for SSH handler.
            proxy_vm_username (str): Proxy VM username for SSH handler.
        Returns:
            bool: True if snapshot was downloaded successfully, False otherwise
        """
        if not self._wait_for_snapshot_completion(user_snapshot=False):
            return False
        self.user_snapshot_ongoing = True
        download_status = self._download_snapshot(
            target_path_on_vm=target_path_on_vm, proxy_vm_address=proxy_vm_address, proxy_vm_username=proxy_vm_username
        )
        self.user_snapshot_ongoing = False
        return download_status

    def switch_serial_to_node(self, node: int):
        """Switches serial output to desired node in runtime.
        It should be called with node ids accordingly to the 'Logging capability - platforms overview' documentation
        (https://confluence.ext.net.nokia.com/display/RFSW/Logging+capability+-+platforms+overview)
         Args:
             node (int): Node id to switch.
         For 5.1 generation RMODs, allowed values are 0 and 1 (0 - Master, 1 - Slave)
         For Scorpio, allowed values are 0,1,2 (0 - Master, 1 - Made1, 2 - Made2)
         For Chile RMODs, allowed value is from range 0-9 (0 - Master, 1 - Stratix1, 2 - DFE0, ... 9 - DFE7)
         For 7.1 generation RMODs, allowed values are 0 and 1-3 (0 - Master, 1-3 - Slaves).
                 The one exception for 7.1 family is Fisto, which has 2xMars nodes.
                 Switch command will not be executed when serial console is connected to Thor node.
         Returns:
             bool: True if getting a switch command was possible and the command was sent, False otherwise
        """
        switch_command = self._get_node_switch_command(node_id=node)
        if switch_command:
            bash_switch_command = f'sudo bash -c "{switch_command}"'
            switch_command = (
                bash_switch_command
                if self.parameters.master_node
                else MASTER_SSH_WRAPPER.format(cmd=bash_switch_command)
            )
            self._send_command(cmd=switch_command, as_rfsw=False)
            time.sleep(3)  # wait for switch to take effect
        return node == self._get_node_number()

    def create_file_preserving_rmod_flags(self):
        """Creates /ram/disable_swman_cleanup file that will preserve RMOD flags i.e. after software update.
        Returns:
            None: Touch command does not return any output when succeeds.
        """
        self._create_file_preserving_rmod_flags()

    def get_rmod_ip(self, wait_time: int = 120):
        """Returns RMOD IP address and waits for it to be set by SMOD.
        Args:
            wait_time (int): The maximum amount of time in seconds for the IP address to be set.
        Returns:
            str: IP address of RMOD.
            list: List of IP addresses of RMODs in case of RF Sharing setup.
            None: In case of IP address not being set or not being able to be determined.
        """
        return self._try_to_determine_rmod_ip(wait_time=wait_time)

    def set_proxy_vm_address_and_username(self, proxy_vm_address: str, proxy_vm_username: str):
        """Sets proxy VM address and username for SSH handler.
        Args:
            proxy_vm_address (str): Proxy VM address.
            proxy_vm_username (str): Proxy VM username.
        Returns:
            None
        """
        self.logger.info(
            f"Setting user proxy VM address {proxy_vm_address} and username {proxy_vm_username} for SSH handler"
        )
        self._set_proxy_vm_address_and_username(proxy_vm_address=proxy_vm_address, proxy_vm_username=proxy_vm_username)

    def set_rmod_credentials(self, password, username="serviceuser"):
        """Sets RMOD credentials for SSH handler.
        Args:
            password (str): RMOD password.
            username (str): RMOD username. Defaults to 'serviceuser'.
        Returns:
            None
        """
        self.logger.info(f"Setting custom RMOD credentials: {username}/{password} for RMOD communication")
        self._set_rmod_credentials(password=password, username=username)

    @property
    def snapshot_path(self):
        """Returns RMOD snapshot path.
           If snapshot was requested by user, then it will restore user snapshot names for download.
        Returns:
            str: Path to the snapshot file.
            None: If snapshot was not created or no snapshot file was found on RMOD's ROM.
        """
        self._restore_user_snapshot_names_for_snapshot_download_on_user_dl_request(request_from_user=True)
        return self.parameters.rom_snapshot_path

    @property
    def rmod_serial_number(self):
        """Returns RMOD serial number.
        Returns:
            str: Serial number of RMOD.
        """
        return self.parameters.ru_config.serial_number

    @property
    def rmod_info(self):
        return self._rsi.get_rmod_info(self.alias)

    def disconnect(self):
        """Disconnects UART connection.
        If debug logs are saved during snapshot collection, then the latest one will be read
        from file to the raw serial log.
        Returns:
            None
        """
        self.logger.debug(f"RMOD's UART connection:{self.alias} - disconnecting request")
        self.logger.info(f"Connection teardown rmod info state: {self.rmod_info}")
        self._wait_for_snapshot_completion(user_snapshot=False)
        self.parameters.is_connected = False
        self.auto_snapshot_start_time = None
        self._stop_thread()
        if self.parameters.rom_extra_logs_path:
            self.logger.info("Dumping RMOD extra logs called with snapshot command")
            log_dump_info = "Logs and information captured during the snapshot process dump"
            self._execute_command(f"echo '<<< {log_dump_info} START >>>'", as_rfsw=False)
            try:
                self._send_command(f"cat {self.parameters.rom_extra_logs_path}", as_rfsw=False)
                self._execute_command(f"echo '>>> {log_dump_info} END <<<'", wait_time=90, as_rfsw=False)
            except Exception as err:
                self.logger.info(f"RSI error during dumping extra logs. Error: {err}")
        self._rsi.download_log(f"{self.parameters.log_dir}/{self.parameters.log_prefix}_raw_serial.log", self.alias)
        self._rsi.teardown(self.alias)
        self.logger.debug(f"RMOD's UART connection:{self.alias} - disconnected")
        self.alias = None

    def download_log(self, target_filepath: str):
        """Downloads current serial connection logs to given file path.
        Args:
            target_filepath (str): Path to file (with file name).
        Returns:
            None
        """
        self.logger.debug(f"Downloading serial interface log to: {target_filepath}")
        self._rsi.download_log(local_path=target_filepath, alias=self.alias)

    def _send_command(self, cmd: str, as_rfsw: bool = True):
        """Sends given command without expecting output.
        Args:
            cmd (str): Command to send.
            as_rfsw (bool): If set to True, then command will be executed as rfsw user. Defaults to True.
        Returns:
            None
        """
        cmd = self.as_rfsw + f"'{cmd}'" if as_rfsw and self.parameters.ru_config.username == "serviceuser" else cmd
        if self.rmod_info.get(RsiState.LOGGED_IN.value):
            self.logger.debug(f"Sending '{cmd}' command")
            self._rsi.send_command(cmd=cmd, alias=self.alias)
            time.sleep(0.25)  # small delay to let command be processed
        else:
            self.logger.info(f"Rmod state is {self.rmod_info}. Sending command: '{cmd}' is not possible yet.")

    def _execute_command(
        self,
        cmd: str,
        elevated=False,
        wait_time: int = 30,
        write_output_to_logs: bool = True,
        with_rsi: bool = True,
        log_execution: bool = True,
        as_rfsw: bool = True,
    ):
        """Sends given command and expects the output.
        Args:
            cmd (str): Command to send.
            elevated (bool): try to run command with elevated permissions. Defaults to False.
            wait_time (int): Wait time to receive data. Defaults to 30.
            write_output_to_logs (bool): By default command output is saved in the log file.
                It may be skipped when output is long, and it is not necessary to have them duplicated with RSI lib.
                Defaults to True.
            with_rsi (bool): If set to True, then RMOD serial interface output buffer will be added to the output.
            log_execution (bool): If set to True, then command execution will be logged.
            as_rfsw (bool): If set to True, then command will be executed as rfsw user. Defaults to True.
        Returns:
            str: Received data or empty sting if data is not a string or if login is not possible.
        """
        cmd = self.as_rfsw + f"'{cmd}'" if as_rfsw and self.parameters.ru_config.username == "serviceuser" else cmd
        elevation_mode = "elevated" if elevated else "normal"
        if not self.rmod_info.get(RsiState.LOGGED_IN.value):
            self.logger.info(f"Rmod state is {self.rmod_info}. Command '{cmd}' execution is not possible yet.")
            return ""
        if not self.parameters.master_node:
            self.logger.info("Command will be executed on RMOD slave node, command result may be unexpected")
        if log_execution:
            self.logger.debug(f"Executing '{cmd}' command with {elevation_mode} permission")
        return self._serial_command_execution_output(cmd, elevated, wait_time, with_rsi, write_output_to_logs)

    def _serial_command_execution_output(self, cmd, elevated, wait_time, with_rsi, write_output_to_logs):
        """Sends a command via RSI and retrieves the output.
        Args:
            cmd (str): Command to send.
            elevated (bool): try to run command with elevated permissions.
            wait_time (int): Wait time to receive data.
            with_rsi (bool): If set to True, then RMOD serial interface output buffer will be added to the output.
            write_output_to_logs (bool): By default command output is saved in the log file.
                It may be skipped when output is long, and it is not necessary to have them duplicated with RSI lib.
        Returns:
            str: Received data or empty sting if data is not a string.
        """
        data = self._rsi.execute_command(cmd=cmd, alias=self.alias, elevated=elevated, timeout=wait_time)
        time.sleep(0.25)  # small delay to let command be processed
        if type(data) is str:
            if write_output_to_logs:
                self.logger.info(f"Command '{cmd}' execution output:\n{data}")
            return data + self._rsi.collect_rmod_output(self.alias) if with_rsi else data
        else:
            return ""

    def _create_file_preserving_rmod_flags(self):
        """Creates /ram/disable_swman_cleanup file that will preserve RMOD flags i.e. after software update.
        Returns:
            None: Touch command does not return any output when succeeds.
        """
        self._send_command("touch /ram/disable_swman_cleanup", as_rfsw=False)

    def _download_snapshot(
        self,
        target_path_on_vm: str,
        nodes_switch_flag: bool = None,
        request_from_user: bool = True,
        proxy_vm_address: str = None,
        proxy_vm_username: str = None,
    ):
        """
        Downloads snapshot from RMOD and saves it on VM PC.
        Args:
            target_path_on_vm (str): Target directory to download a snapshot file.
            nodes_switch_flag bool: Flag for switching nodes in startup - restore or set after downloading snapshot.
            Defaults to None (flag will stay as it currently is).
            request_from_user (bool): If True, then user has been requested snapshot download.
            proxy_vm_username (str): Proxy VM username for SSH handler.
            proxy_vm_address (str): Proxy VM address for SSH handler.
        Returns:
            bool: True if snapshot was downloaded successfully, False otherwise.
        """
        if proxy_vm_address and proxy_vm_username:
            self.logger.info(
                f"Proxy VM address {proxy_vm_address} and username {proxy_vm_username} "
                "for SSH handler provided by user for snapshot download"
            )
            self._set_proxy_vm_address_and_username(
                proxy_vm_address=proxy_vm_address, proxy_vm_username=proxy_vm_username
            )
        self._setup_rmod_connection_network_params_for_snapshot_download()
        if nodes_switch_flag is not None:
            self.parameters.ru_config.switch_nodes = nodes_switch_flag
        if self.parameters.ips_from_rmod is None:
            self.logger.error("Cannot get RMOD's IP. Moving snapshot to VM is not possible!")
            return False
        self._restore_user_snapshot_names_for_snapshot_download_on_user_dl_request(request_from_user)
        self._try_to_determine_full_rack_smod()
        self._copy_snapshot_and_debug_file_from_rmod_to_vm(target_path_on_vm)
        self.user_snapshot_and_debug_files_for_download = set()
        return True

    def _restore_user_snapshot_names_for_snapshot_download_on_user_dl_request(self, request_from_user: bool):
        """Restores snapshot and extra logs names triggered by the user for snapshot download after user request.
        Args:
            request_from_user (bool): If True, then user has been requested snapshot download.
        Returns:
            None
        """
        if not request_from_user:
            self.logger.debug("Requested auto snapshot download")
            return

        self._wait_for_snapshot_completion(user_snapshot=False)
        self.logger.info("Restoring RMOD connection parameters for snapshot download")

        if not self.user_snapshot_and_debug_files_for_download:
            self.parameters.rom_snapshot_path = None
            self.parameters.rom_extra_logs_path = None
            return
        self._restore_snapshot_and_logs_paths()

    def _restore_snapshot_and_logs_paths(self):
        """Restores the snapshot and extra logs paths if files exist."""
        for snapshot, debug_file in self.user_snapshot_and_debug_files_for_download:
            if snapshot.startswith("/mnt/runtime/snapshot") and self._confirm_file_exists_on_master_node(snapshot):
                self.logger.info(f"Snapshot file {snapshot} exists, restoring connection parameters")
                self.parameters.rom_snapshot_path = snapshot
                self.parameters.rom_extra_logs_path = debug_file
                break
            self._handle_missing_files(snapshot, debug_file)

    def _handle_missing_files(self, snapshot, debug_file):
        """Handles cases where snapshot or debug files are missing."""
        if snapshot.startswith("/mnt/runtime/snapshot"):
            self.logger.debug(f"File for snapshot download {snapshot} does not exist!")
            self.parameters.rom_snapshot_path = None
            if not self._confirm_file_exists_on_master_node(debug_file):
                self.logger.debug(f"File for extra logs download {debug_file} does not exist!")
                self.parameters.rom_extra_logs_path = None

    def _is_uart_connection_established(self):
        """
        Calls setup uart connection function for every configured UART on RMOD and checks if successful.
        Returns:
            bool: True if any UART connection is established, False otherwise.
        """
        return self._setup_uart_connection()

    def _setup_uart_connection(self):
        """
        Setups connection to single diagnostic card's UART. It starts thread for connection loop.
        Returns:
            bool: False if setting up connection or logger failed. True otherwise.
        """
        self.logger.debug(f"Logger initialized for a connection with alias:{self.alias}\n{self.parameters}")
        self.logger.info(f"Connection start rmod info state: {self.rmod_info}")
        self._confirm_node_and_serial_number()
        self._try_to_ping_and_set_slave_node()
        self._send_commands_after_connected()
        self.auto_snapshot_start_time = time.time() + 10 if self.parameters.master_node else None
        return self._start_thread_for_connection_loop()

    def _send_commands_after_connected(self):
        """Sends commands after connection is established.
        Returns:
            None
        """
        if self.parameters.ru_config.commands_after_connect:
            for command in self.parameters.ru_config.commands_after_connect:
                self._send_command(command, as_rfsw=False)
        else:
            self.logger.debug("No commands to send after connection established")

    def _start_thread_for_connection_loop(self):
        """Starts a thread and connection loop for diagnostic card's UART
        Returns:
            bool: True when thread was created, False otherwise.
        """
        alias = self.alias
        if self._thread is None or not self._thread.is_alive():
            try:
                self._stop_event.clear()
                self._thread = threading.Thread(target=self._connection_event_loop, daemon=True)
                self._thread.start()
                self.logger.debug(f"Thread for alias:{self.alias} started.")
                self.logger.info(f"Started connection loop for RMOD alias: {alias}!")
                return True
            except (threading.ThreadError, ValueError) as e:
                self.logger.error(f"Cannot start connection loop for alias:{alias}. Reason: {e}")
        return False

    def _stop_thread(self):
        if self._thread and self._thread.is_alive():
            self._stop_event.set()
            self._thread.join(timeout=10)
            if self._thread.is_alive():
                self.logger.warning(f"Thread for alias:{self.alias} did not stop within timeout!")
            else:
                self.logger.info(f"Thread for alias:{self.alias} stopped and cleaned up.")
        self._thread = None

    def _create_file_preserving_flags_if_logged_in(self):
        """When connection is just created and rmod console state is logged in,
           then empty file for preserving flags function is called.
        Returns:
            None
        """
        if self.rmod_info.get(RsiState.LOGGED_IN.value) and self.parameters.ru_config.preserve_flags:
            self.create_file_preserving_rmod_flags()

    def _remove_previous_snapshot_files(self):
        """When connection is just created and rmod console state is logged in,
           then non-volatile memory snapshot directory is removed on each connected RMOD.
        Returns:
            None
        """
        if self.rmod_info.get(RsiState.LOGGED_IN.value) and not self.parameters.second_uart:
            self._send_command(
                cmd=f"cd {self._rom} && rm -rf {self._rom_user_snapshot_dir} {self._rom_auto_snapshot_dir}"
            )

    def _try_to_get_info_about_rmod_reset(self, wait_time: int):
        """Tries to get rmod restart steps: Uboot startup, LFS Startup and Login prompt readiness based on statuses
        received with rmod_serial_interface states.
        Args:
            wait_time (int): The maximum amount of time in seconds for the restart to complete.
        Returns:
            (bool): True if RMOD restart was successful and login is possible, False otherwise.
        """
        start_time = time.time()

        if not self._wait_for(
            lambda: self.rmod_info.get(RsiState.UBOOT_DETECTED.value)
            and not self.rmod_info.get(RsiState.LOGIN_POSSIBLE.value),
            start_time,
            wait_time,
            self.logger.debug,
            f"Rmod {self.parameters.ru_config.serial_number} "
            "uboot start initialization detected after requested reboot",
            f"Rmod {self.parameters.ru_config.serial_number} uboot start not detected within {wait_time}s!",
        ):
            return False

        if not self._wait_for(
            lambda: not self.rmod_info.get(RsiState.UBOOT_DETECTED.value),
            start_time,
            wait_time,
            self.logger.debug,
            f"Rmod {self.parameters.ru_config.serial_number} uboot start complete detected for requested reboot",
            f"Rmod {self.parameters.ru_config.serial_number} uboot successful start not confirmed!",
        ):
            return False

        if not self._wait_for(
            lambda: self.rmod_info.get(RsiState.LOGIN_POSSIBLE.value),
            start_time,
            wait_time,
            self.logger.info,
            f"Finished wait for reboot. Radio {self.parameters.ru_config.serial_number} "
            "restart completed successfully!",
            f"Rmod {self.parameters.ru_config.serial_number} reboot within {wait_time}s "
            "not completed to login readiness!",
            break_on_true=True,
        ):
            return False
        return True

    def _wait_for(
        self,
        condition: callable,
        start_time: float,
        wait_time: int,
        log_func: callable,
        log_msg: str,
        error_msg: str,
        break_on_true: bool = True,
    ):
        """Waits for a condition to be met within a specified time.
        Args:
            condition (callable): A callable that returns True when the condition is met.
            start_time (float): The time when the wait started.
            wait_time (int): The maximum amount of time to wait in seconds.
            log_func (callable): A logging function to call when the condition is met.
            log_msg (str): The message to log when the condition is met.
            error_msg (str): The message to log if the wait times out.
            break_on_true (bool): If True, break the loop when the condition is met.
        Returns:
            (bool): True if the condition was met within the wait time, False otherwise.
        """
        wait_interval = 3
        while time.time() - start_time < wait_time:
            if condition():
                log_func(log_msg)
                if break_on_true:
                    return True
            time.sleep(wait_interval)
        self.logger.error(error_msg)
        return False

    def _connection_event_loop(self):
        """Initialises the loop and keeps until connection is not closed.
           It checks for changes in rmod_info and reacts to them.
           It checks for slave node timeout and if it is set, then it checks if current time reaches the timeout.
           It checks for active faults that require auto snapshot.
        Returns:
            None
        """
        saved_rmod_info = self.rmod_info
        while not self._stop_event.is_set():
            time.sleep(0.2)
            try:
                if self.parameters.is_connected and self.alias is not None:
                    current_rmod_info = self.rmod_info
                    rmod_info_changed = dict(current_rmod_info.items() - saved_rmod_info.items())
                    saved_rmod_info = current_rmod_info
                    if rmod_info_changed:
                        self.logger.debug(f"Received change from RSI: {rmod_info_changed}")
                        self._handle_rmod_info_status_change(rmod_info_changed)
                    self._check_slave_node_timeout()
                    self._check_faults_for_auto_snapshot()
                else:
                    self.logger.debug("Closed connection to the diagnostic card")
                    break
            except Pyro4.errors.CommunicationError as e:
                self.logger.error(f"Lost connection to RSI: {e}\n{traceback.format_exc()}")
                self.parameters.is_connected = False
                self._stop_event.set()
                break
            except Exception as e:
                self.logger.error(
                    f"Exception for diagnostic card connection is not handled. "
                    f"Reason: {e}\n{traceback.format_exc()}"
                )
        self.logger.debug("Exited connection loop. Thread closed")

    def _check_slave_node_timeout(self):
        """Checks if slave node timeout is set, if it is, then checks if current time reaches the timeout.
        Until timeout is not reached, it is assumed that serial console is getting slave logs.
        Returns:
            None
        """
        if self.parameters.slave_node_timeout and time.time() > self.parameters.slave_node_timeout:
            self._handle_console_switch_back_to_master_procedure()

    def _handle_console_switch_back_to_master_procedure(self):
        """Handles the procedure of switching console output back to master node after slave node timeout.
        If console is not switched back to master node, it handles the slave node timeout.
        Returns:
            None
        """
        if self._check_if_console_switched_back_to_master():
            self._handle_console_switch_back_status()
        else:
            self._handle_slave_node_timeout()

    def _check_if_console_switched_back_to_master(self):
        """Checks if console output is switched back to master node.
        Returns:
            (bool): True if console output is switched back to master node, False otherwise.
        """
        current_node = self._get_node_number()
        if current_node is None:
            self.logger.debug("Cannot determine current node number, cannot check if console switched back to master.")
            return False
        if not self.parameters.master_node:
            self.logger.debug("Console output is not switched back to master node yet...")
            return False
        return True

    def _handle_console_switch_back_status(self):
        """Handles the status of console switch back to master node, by updating parameters and logs the information.
        Returns:
            None
        """
        self.parameters.slave_node_timeout = None
        self.logger.info(
            "Console output switched back to master node. Current rmod "
            f"serial connection states are:\n {self.rmod_info}"
        )

    def _handle_slave_node_timeout(self):
        """Handles the slave node timeout. If timeout is reached, it logs the information and updates parameters.
        Returns:
            None
        """
        if not hasattr(self, "_slave_timeout_extended"):
            timeout_extension = 15
            self.parameters.slave_node_timeout = time.time() + timeout_extension
            self._slave_timeout_extended = True
            self.logger.debug(
                "First attempt to switch console output back to master node failed. "
                f"Waiting additional {timeout_extension} seconds before next attempt..."
            )
        else:
            self.parameters.slave_node_timeout = None
            del self._slave_timeout_extended
            self._handle_recovery_switch_back_to_master()

    def _handle_recovery_switch_back_to_master(self):
        """Handles the recovery switch back to master node after slave node timeout.
        Returns:
            None
        """
        self.logger.info("Slave node timeout reached. Trying to switch console output back to master node...")
        if self._try_to_switch_and_check_if_console_is_master():
            self._handle_console_switch_back_status()
        else:
            self.logger.info(
                "Console switch back to master unsuccessful. "
                "Console output will remain on slave node until manually switched back."
            )

    def _try_to_switch_and_check_if_console_is_master(self):
        """Tries to switch console output back to master node and checks if it is successful after waiting.
        Returns:
            (bool): True if console output is switched back to master node, False otherwise.
        """
        wait_time_for_switch = 5
        back_to_master_cmd = f'sudo bash -c "{self.parameters.ru_config.master_node_switch_cmd}"'
        self._send_command(MASTER_SSH_WRAPPER.format(cmd=back_to_master_cmd), as_rfsw=False)
        time.sleep(wait_time_for_switch)
        return self._check_if_console_switched_back_to_master()

    def _handle_rmod_info_status_change(self, rmod_info_changed: dict):
        """Function reads the change and calls the function to react properly to the change.
        Args:
            rmod_info_changed (dict): detected change of rmod information from rmod_serial_interface.
            Note that if keyword exists, then possible values are True or False and None otherwise.
        Returns:
            None
        """
        handlers = {
            RsiState.REBOOT_DETECTED.value: self._handle_reboot_state_change,
            RsiState.UBOOT_DETECTED.value: self._handle_uboot_state_change,
            RsiState.CONNECTED.value: self._handle_connection_state_change,
            RsiState.LOGIN_POSSIBLE.value: self._handle_login_possible_state_change,
            RsiState.LOGGED_IN.value: self._handle_logged_in_state_change,
        }

        for state, handler in handlers.items():
            if rmod_info_changed.get(state) is not None:
                handler(rmod_info_changed)

    def _handle_reboot_state_change(self, rmod_info_changed: dict):
        """Handles observed reboot state changes.
         Change to reboot detected means that RMOD restart was requested and it is in progress.
         Change to False means that RMOD restart is completed.
         Args:
            rmod_info_changed (dict): detected change of rmod information from rmod_serial_interface
        Returns:
            None
        """
        if rmod_info_changed.get(RsiState.REBOOT_DETECTED.value):
            self.logger.info("Reboot detected, waiting for RMOD to restart")
        else:
            self.logger.info("Reboot state changed to False, RMOD restart completed")

    def _handle_logged_in_state_change(self, rmod_info_changed: dict):
        """Handles observed logged in state changes.
         Change to logged in means that sending and executing commands is possible after f.ex. RMOD restart,
         whereas change to False means that user is logged out and no commands will be sent.
         Args:
            rmod_info_changed (dict): detected change of rmod information from rmod_serial_interface
        Returns:
            None
        """
        if rmod_info_changed.get(RsiState.LOGGED_IN.value):
            self._handle_status_change_to_logged_in()
        else:
            self.logger.info("Logged in state changed to False. User is logged out!")

    def _handle_login_possible_state_change(self, rmod_info_changed: dict):
        """Handles observed login possibility state changes.
         Change to log in possible means that console waits for provided credentials after f.ex. RMOD restart.
        Returns:
            None
        """
        if rmod_info_changed.get(RsiState.LOGIN_POSSIBLE.value):
            self.logger.debug("Login is possible, trying to send command to get node_id and to log in")
            self.logger.info(
                self._serial_command_execution_output(
                    cmd=GET_NODE, elevated=False, with_rsi=False, write_output_to_logs=True, wait_time=1
                )
            )
        else:
            self.logger.debug("Login possible state changed to False")

    def _handle_status_change_to_logged_in(self):
        """Handles observed logged in state change from False->True.
         Change to logged in means that sending and executing commands is possible after f.ex. RMOD restart
         and all automatic features will be started.
        Returns:
            None
        """
        self.logger.debug(f"Console logged in on node: {self._get_node_number()}, handling post-login actions")
        if self.parameters.ru_config.preserve_flags:
            self._create_file_preserving_rmod_flags()
        self._send_commands_after_login_master()
        if self.parameters.ru_config.switch_nodes:
            self._try_to_get_slave_node_startup_logs()
        if self.parameters.ru_config.auto_snapshot_on_fault:
            self.logger.info("Auto snapshot on fault is enabled, but it will not be triggered on slave nodes.")
        self._send_commands_after_login_slave()

    def _check_faults_for_auto_snapshot(self):
        """Checks if there are any active faults that require auto snapshot.
           If there are critical active faults, then snapshot will be taken.
           If there are normal active faults, then snapshot will be taken only if auto snapshot is enabled.
        Returns:
            None
        """
        if not self._should_the_alarms_check_be_skipped():
            new_active_faults_ids = self._analyze_active_faults()
            if new_active_faults_ids:
                self._take_auto_snapshot(new_active_faults_ids)

    def _should_the_alarms_check_be_skipped(self):
        """Checks if the alarms check should be skipped.
           If all setup conditions are met, then it checks to trigger alarms check every minute.
        Returns:
            (bool): True if the alarms check should be skipped, False otherwise.
        """
        return (
            self._skip_due_to_auto_snapshot_disabled()
            or self._skip_due_to_connection_state()
            or self._skip_due_to_timers()
        )

    def _skip_due_to_timers(self):
        """Checks if the slave node timeout is set or if the auto snapshot start time is not a multiple of 60 seconds.
        Returns:
            (bool): True if the alarms check should be skipped, False otherwise.
        """
        return bool(self.parameters.slave_node_timeout) or int(time.time() - self.auto_snapshot_start_time) % 60 != 0

    def _skip_due_to_auto_snapshot_disabled(self):
        """Checks if the auto snapshot state imposes alarms check to be skipped.
        Returns:
            (bool): True if the auto snapshot on fault is disabled, False otherwise.
        """
        return (
            not self.parameters.ru_config.auto_snapshot_on_fault
            or not self.auto_snapshot_start_time
            or not self.parameters.master_node
        )

    def _skip_due_to_connection_state(self):
        """Checks if the connection state imposes alarms check to be skipped.
        Returns:
            (bool): True if alarms check should be skipped, False otherwise.
        """
        current_rmod_info = self.rmod_info
        return (
            current_rmod_info.get(RsiState.UBOOT_DETECTED.value)
            or current_rmod_info.get(RsiState.REBOOT_DETECTED.value)
            or not current_rmod_info.get(RsiState.LOGIN_POSSIBLE.value)
            or not current_rmod_info.get(RsiState.LOGGED_IN.value)
            or not current_rmod_info.get(RsiState.CONNECTED.value)
        )

    def _analyze_active_faults(self):
        """Analyzes active faults and checks if there are any new critical or normal alarms.
        Returns:
            list: List of new active faults IDs that require snapshot.
            If there are no new active faults, then empty list is returned.
        """
        pattern = r"<(.*?)>.*?\((\d+)\)"
        raised_critical = self._check_for_new_critical_alarms(pattern)
        raised_normal = self._check_for_new_normal_alarms(pattern)
        return raised_critical + raised_normal

    def _check_for_new_normal_alarms(self, pattern: str):
        """Checks for new normal active alarms and returns list of raised faults that require snapshot.
           Normal active faults are those that are not critical and are defined in RU configuration.
           They are expected to be raised multiple times, so they are counted and checked against expected raise time.
        Args:
            pattern (str): Regular expression pattern to match the normal active faults.
        Returns:
            list: List of raised normal active faults IDs that require snapshot.
            If there are no new normal active faults, then empty list is returned.
        """
        raised_faults_to_get_snapshot = []
        normal_faults_output = self._execute_command(
            GET_NORMAL_FAULTS_CMD, write_output_to_logs=False, log_execution=False, as_rfsw=False
        )
        normal_faults = [str(fault) for fault in self.parameters.ru_config.normal_faults.keys()]
        for raise_time, fault_id in re.findall(pattern, normal_faults_output):
            if fault_id in normal_faults:
                expected_raise_time = self.parameters.ru_config.normal_faults.get(int(fault_id))
                self._normal_active_faults[fault_id].append(raise_time)
                self.logger.debug(
                    f"Normal active observed FID:{fault_id} is raised at {raise_time} and "
                    f"visible for #{self._normal_active_faults[fault_id].count(raise_time)} time"
                )
                if self._normal_active_faults[fault_id].count(raise_time) == expected_raise_time:
                    raised_faults_to_get_snapshot.append(fault_id)
                    self.logger.info(
                        f"Normal active RMOD {self.parameters.ru_config.radio_type}:"
                        f"{self.parameters.ru_config.serial_number} fault detected: {fault_id} "
                        f"at {raise_time} and was visible for {expected_raise_time} times"
                    )
        return raised_faults_to_get_snapshot

    def _check_for_new_critical_alarms(self, pattern: str):
        """Checks for new critical active alarms and returns list of raised faults that require snapshot.
           Critical active faults are those that are defined in RU configuration as critical faults.
           They are expected to be raised only once, so they are checked against their timestamp.
        Args:
            pattern (str): Regular expression pattern to match the critical active faults.
        Returns:
            list: List of raised critical active faults IDs that require snapshot.
            If there are no new critical active faults, then empty list is returned.
        """
        raised_faults_to_get_snapshot = []
        critical_faults_output = self._execute_command(
            GET_CRITICAL_FAULTS_CMD, write_output_to_logs=False, log_execution=False, as_rfsw=False
        )
        for raise_time, fault_id in re.findall(pattern, critical_faults_output):
            if (
                raise_time not in self._critical_active_faults.get(fault_id, [])
                and int(fault_id) in self.parameters.ru_config.critical_faults
            ):
                raised_faults_to_get_snapshot.append(fault_id)
                self._critical_active_faults[fault_id].add(raise_time)
                self.logger.warning(
                    f"Critical active RMOD {self.parameters.ru_config.radio_type}:"
                    f"{self.parameters.ru_config.serial_number} fault detected: "
                    f"{fault_id} at {raise_time}"
                )
        return raised_faults_to_get_snapshot

    def _send_commands_after_login_master(self):
        """Sends commands after login on master node.
        Returns:
            None
        """
        if self.parameters.ru_config.commands_after_login_master and self.parameters.master_node:
            for command in self.parameters.ru_config.commands_after_login_master:
                self._send_command(command, as_rfsw=False)

    def _send_commands_after_login_slave(self):
        """Sends commands after login on slave node.
        Returns:
            None
        """
        if self.parameters.ru_config.commands_after_login_slave and not self.parameters.master_node:
            for command in self.parameters.ru_config.commands_after_login_slave:
                self._send_command(command, as_rfsw=False)

    def _handle_connection_state_change(self, rmod_info_changed: dict):
        """Handles observed connection state change and informs about it with proper log level.
        Args:
            rmod_info_changed (dict): a dictionary with RMOD connection state or states change.
        Returns:
            None
        """
        if not rmod_info_changed.get(RsiState.CONNECTED.value):
            self.logger.error(f"Serial connection with RMOD {self.parameters.ru_config.serial_number} lost")
        else:
            self.logger.info("Lost serial connection with RMOD restored")

    def _handle_uboot_state_change(self, rmod_info_changed: dict):
        """Handles observed uboot state change (possible restart) and informs about it.
        Args:
            rmod_info_changed (dict): a dictionary with RMOD connection state or states change.
        Returns:
            None
        """
        current_node = "master" if self.parameters.master_node else "slave"
        if rmod_info_changed.get(RsiState.UBOOT_DETECTED.value):
            self.logger.info(f"Rmod Uboot startup detected on {current_node} node")
        else:
            self.logger.info(f"Rmod Uboot startup done on {current_node} node")

    def _try_to_determine_rmod_ip(self, wait_time: int = 120):
        """Tries to determine RMOD IP address by executing 'ifconfig' command.
        Args:
            wait_time (int): The maximum amount of time in seconds for the IP address to be set. Defaults to 120s.
        Returns:
            str/list[str]: IP address in case of standalone RMOD connection or IP addresses of RMOD in RF Sharing mode.
            None: In case of IP address not being set or not being able to be determined.
        """
        get_ip_cmd = "ip a | grep inet || /sbin/ip a | grep inet"
        get_ip_cmd = get_ip_cmd if self.parameters.master_node else MASTER_SSH_WRAPPER.format(cmd=get_ip_cmd)
        local_ips = ("192.168", "127.0.0", "10.10")
        interval = 5
        start_time = time.time()
        attempt = 0
        while time.time() - start_time < wait_time:
            attempt += 1
            command_output = self._execute_command(get_ip_cmd, as_rfsw=False)
            ip_addresses = re.findall(r"inet (\d+\.\d+\.\d+\.\d+)", command_output)
            ip_addr = [ip for ip in ip_addresses if not ip.startswith(local_ips)]
            if len(ip_addr) == 0:
                self.logger.debug(f"RMOD IP address not found in attempt {attempt} of {wait_time // interval}.")
                time.sleep(interval)
                continue
            elif len(ip_addr) == 1:
                self.parameters.ips_from_rmod = ip_addr
                self.parameters.ip_from_smod = ip_addr[0]
                self.logger.info(f"RMOD IP address found: {self.parameters.ip_from_smod}")
                return self.parameters.ip_from_smod
            else:
                self.logger.info(f"Multiple RMOD IP addresses found: {ip_addr}")
                self.parameters.ips_from_rmod = ip_addr
                return self.parameters.ips_from_rmod
        return None

    def _confirm_node_and_serial_number(self):
        """Confirms if the node is the master node and confirms initial serial number with one read from the hardware.
        Returns:
            None
        Raises:
            SerialNumberNotMatchedError: If the serial number from the RMOD does not match the initial serial number.
        """
        node_number = self._get_node_number()
        init_rmod_serial_number = self.parameters.ru_config.serial_number
        hw_serial_number = self._rsi.get_rmod_serial_number(self.alias)
        core_assembly_sn = "/mnt/factory/configs/unit/core_assembly_serial_number.txt"
        if node_number is not None:
            if self.parameters.master_node:
                if (
                    init_rmod_serial_number.strip() in hw_serial_number.strip()
                    or init_rmod_serial_number.strip()
                    in self._execute_command(f"cat {core_assembly_sn}", as_rfsw=False, elevated=True).strip()
                ):
                    self.logger.info(
                        f"RMOD SN:{init_rmod_serial_number} verified successfully on HW, "
                        f"connected to MASTER node_id: {node_number}"
                    )
                else:
                    raise SerialNumberNotMatchedError(
                        f"RMOD init SN:{init_rmod_serial_number} not matched " f"with HW SN:{hw_serial_number}"
                    )
            else:
                self.logger.info(
                    f"RMOD {init_rmod_serial_number} connected to SLAVE node_id: {node_number}, Master"
                    f" node_id is expected from the set: {self.parameters.ru_config.master_node_ids}"
                )
                self.logger.info(f"Hostname RMOD ID:{hw_serial_number}")
                self._check_for_thor_node()
                if not self.parameters.second_uart:
                    self.logger.info("Trying to redirect serial console to master node...")
                    self._try_to_switch_and_check_if_console_is_master()
        else:
            self.logger.warning(f"RMOD {init_rmod_serial_number} couldn't be verified on HW")

    def _check_for_thor_node(self):
        """Checks if the current node is Thor and if the radio family is one of Grogu, Fisto, or Yoda.
        Returns:
            None
        """
        if (
            self.parameters.ru_config.radio_family
            in [
                "Grogu",
                "Fisto",
                "Yoda",
            ]
            and "thor" in self._execute_command("hostname").lower()
        ):
            self.logger.warning(
                "Connection to Thor node. Please check configuration for switched port declaration."
                " Switching nodes and snapshot disabled!"
            )
            self.parameters.second_uart = True

    def _get_node_number(self):
        """Gets node number from the command output.
        Returns:
            int: The node number to which console is connected.
            None: If serial console lines containing the output was not read.
        """
        get_node_cmd = 'echo "Serial console connected to node`get_node_id`"'
        get_node_id_output = self._execute_command(get_node_cmd, as_rfsw=False)
        match = re.search(r"node(\d{1,2})", get_node_id_output)
        if match:
            current_node = int(match.group(1))
            self._determine_mode_of_the_node(current_node)
            return current_node
        else:
            self.logger.info("Node number not found in the command output")
            return None

    def _determine_mode_of_the_node(self, current_node: int):
        """Determines if the current node is master or slave and sets the parameters accordingly.
        Args:
            current_node (int): The current node number.
        Returns:
            None
        """
        if current_node in self.parameters.ru_config.master_node_ids:
            self.logger.info(f"Current node number determined: {current_node} (master node)")
            self.parameters.master_node = True
            self.parameters.master_node_id = current_node
        else:
            self.logger.info(f"Current node number determined: {current_node} (slave node)")
            self.parameters.master_node = False
            self.parameters.slave_node_present = True

    def _try_to_ping_and_set_slave_node(self):
        """Tries to send ping to slave node and sets slave_node field to True if response received.
           First two slave IPs are pinged, if both are not reachable, then it is assumed that slave node is not present.
        Returns:
           None
        """
        slave_ip_2 = "192.168.100.2"
        slave_ip_3 = "192.168.100.3"
        ping_ip2_output = self._execute_command(PING_CMD.format(ip=slave_ip_2), as_rfsw=False)
        ping_ip3_output = self._execute_command(PING_CMD.format(ip=slave_ip_3), as_rfsw=False)
        if PING_LOSS in ping_ip2_output + self._rsi.collect_rmod_output(
            self.alias
        ) and PING_LOSS in ping_ip3_output + self._rsi.collect_rmod_output(self.alias):
            self.logger.info(
                f"Pinging slave node with IP {slave_ip_2} and {slave_ip_3} fails. Assuming no nodes are present"
            )
        else:
            self.logger.debug("Pinging slave node successful")
            self.parameters.slave_node_present = True

    def _try_to_get_slave_node_startup_logs(self):
        """Tries to get slave node startup logs by switching serial console output to slave node
         and after time in which slave node should be started and stable back to master node.
        Returns:
            None
        """
        if self.parameters.is_connected and self.parameters.master_node and self.parameters.slave_node_present:
            switch_to_slave_cmd = self.parameters.ru_config.default_slave_node_switch_cmd
            switch_back_to_master_cmd = self.parameters.ru_config.master_node_switch_cmd
            if switch_to_slave_cmd is not None:
                self._send_switch_command_and_set_slave_timer(
                    switch_to_slave=switch_to_slave_cmd, switch_back_to_master=switch_back_to_master_cmd
                )
            else:
                self.logger.info(
                    "Cannot get switch command for slave node: "
                    f"{self.parameters.ru_config.current_switch_slave_node_id}. "
                    "In case of custom connection setup, please check if correct value is provided!"
                )

    def _get_node_switch_command(self, node_id: int):
        """Tries to get slave node command to be used for serial console output switching on RMOD.
        Args:
            node_id (int): Node id number, where 0 is master node and next numbers are slave nodes.
        Returns
            str: console output switch command or None.
        """
        try:
            return self.parameters.ru_config.switch_commands[node_id]
        except IndexError:
            self.logger.warning(
                f"Cannot get switch command for node id:{node_id}. "
                "In case of custom connection setup, please check if correct value is provided!"
            )
            return None

    def _send_switch_command_and_set_slave_timer(self, switch_to_slave: str, switch_back_to_master: str):
        """Sends the devmem based command to switch console output and sets slave node timer.
        Args:
            switch_to_slave (str): command for switching console to the other node.
            switch_back_to_master (str): command switching back console to the master node
        Returns:
            None
        """
        time_to_read_slave_logs = self.parameters.ru_config.output_switch_seconds
        switch_command = (
            f"sudo bash -c '({switch_to_slave} && "
            f"sleep {time_to_read_slave_logs} && "
            f"{switch_back_to_master}) &'"
        )
        self.logger.info(f"Switching console output for {time_to_read_slave_logs}s to get slave node startup logs")
        self._send_command(switch_command, as_rfsw=False)
        self.parameters.slave_node_timeout = time.time() + time_to_read_slave_logs

    def _take_snapshot(
        self,
        target_path_on_vm: str = None,
        reset_rmod: bool = False,
        stop_and_fix: bool = False,
        skip_downloading: bool = False,
        timeout: int = 180,
        auto_snapshot: bool = False,
        new_active_faults_ids: list = None,
        proxy_vm_address: str = None,
        proxy_vm_username: str = None,
    ):
        """Takes snapshot from RMOD and saves it on VM connected to the serial console board.
        Additional debug logs from RMOD are collected and saved to the debug log file.
        Args:
            target_path_on_vm (str): Target directory to download a snapshot file. If None, then it will be saved to
            RMOD ROM only without downloading
            reset_rmod (bool): reset command will be sent to the RMOD if set to True, for example when FID:10 detected,
                Defaults to False.
            stop_and_fix (bool): The master flag to do not reset RMOD even if asked, for example determined by FID:10.
                Defaults to False.
            skip_downloading (bool): If set to True, then file will be created in RMOD's ROM and not downloaded to VM.
                It is useful when snapshot is created in case of connection problems and can be moved after recovery.
            timeout (int): time in seconds to execute snapshot command (downloading time is not counted).
                Defaults to 180.
            auto_snapshot (bool): If True, then snapshot is taken automatically after active faults are detected.
            new_active_faults_ids (list): List of new active faults IDs that require auto snapshot.
            proxy_vm_address (str): Proxy VM address for SSH handler.
            proxy_vm_username (str): Proxy VM username for SSH handler.
        Returns:
            bool: True only if snapshot created in RMODs ROM and copied to VM, False otherwise
        """
        if not self._execute_snapshot(timeout, auto_snapshot, new_active_faults_ids):
            return False
        switch_flag = self.parameters.ru_config.switch_nodes
        if not self._move_snapshot_and_extra_logs_from_ram_to_rom():
            return self._try_to_copy_snapshot_and_extra_logs_to_vm_from_ram(target_path_on_vm)
        self._reset_rmod_if_requested(reset_rmod, stop_and_fix)
        if skip_downloading:
            self.logger.info("Skipping downloading of the snapshot.")
            return True
        request_from_user = not auto_snapshot
        return self._download_snapshot(
            target_path_on_vm,
            nodes_switch_flag=switch_flag,
            request_from_user=request_from_user,
            proxy_vm_address=proxy_vm_address,
            proxy_vm_username=proxy_vm_username,
        )

    def _reset_rmod(self, wait_time: int):
        """Resets RMOD by sending reboot command and waits for RMOD to be ready for login.
        Args:
            wait_time (int): The maximum amount of time in seconds for the RMOD to be ready for login.
        Returns:
            None
        """
        self.logger.info("Resetting radio.")
        reboot_cmd = (
            "sudo reboot || sudo /sbin/reboot"
            if self.parameters.ru_config.username == "serviceuser"
            else "reboot || /sbin/reboot"
        )
        self._send_command(reboot_cmd, as_rfsw=False)
        self.logger.debug(f"Waiting up to {wait_time}s.")
        if self._try_to_get_info_about_rmod_reset(wait_time):
            self.parameters.ram_extra_logs_path = None
            self.parameters.ram_snapshot_path = None

    def _reset_rmod_if_requested(self, reset_rmod: bool, stop_and_fix: bool):
        """Resets RMOD if requested by the user or if stop_and_fix is set to False.
        Args:
            reset_rmod (bool): If True, then RMOD will be reset.
            stop_and_fix (bool): If True, then RMOD will not be reset even if reset_rmod is True.
        Returns:
            None
        """
        if reset_rmod and not stop_and_fix:
            wait_time = 100
            self.logger.debug("Before copying snapshot to VM RMOD will be reset.")
            self.parameters.ru_config.switch_nodes = False
            self._reset_rmod(wait_time)

    def _take_auto_snapshot(self, new_active_faults_ids: list):
        """Takes auto snapshot on RMOD if there are new active faults that require snapshot.
        Args:
            new_active_faults_ids (list): List of new active faults IDs that require auto snapshot.
        Returns:
            bool: True if auto snapshot was taken successfully, False otherwise.
        """
        if not self._wait_for_snapshot_completion(user_snapshot=True):
            return False
        self.auto_snapshot_ongoing = True
        self.logger.info("Taking auto snapshot on RMOD")
        snapshot_status = self._take_snapshot(auto_snapshot=True, new_active_faults_ids=new_active_faults_ids)
        self.auto_snapshot_ongoing = False
        return snapshot_status

    def _wait_for_snapshot_completion(self, user_snapshot: bool = False):
        """Waits for both snapshot ongoing flags to be false.
        Returns:
            bool: True if snapshot command completed successfully, False otherwise.
        """
        timeout = 300
        start_time = time.time()
        self.logger.info(f"Waiting for for possible ongoing snapshot to complete within {timeout}s")
        while time.time() - start_time < timeout:
            if user_snapshot:
                if not self.user_snapshot_ongoing:
                    return True
            else:
                if not self.auto_snapshot_ongoing:
                    return True
            time.sleep(1)
        self.logger.error(f"Snapshot command did not complete within the expected {timeout}s time.")
        return False

    def _execute_snapshot(self, timeout: int, auto_snapshot: bool = False, new_active_faults_ids: list = None):
        """Executes snapshot command on RMOD, confirms that snapshot file and extra debug file
         exist in /ram of the master node.
        Args:
            timeout (int): time in seconds to execute snapshot command (downloading time is not counted).
            auto_snapshot (bool): If True, then snapshot is taken automatically after active faults are detected.
            new_active_faults_ids (list): List of new active faults IDs that require auto snapshot.
        Returns:
            bool: True if execution of snapshot command was possible, False otherwise.
        """
        if not self.rmod_info.get(RsiState.LOGGED_IN.value):
            self.logger.error(
                "Snapshot command execution is not possible.\nStatus of "
                f"{self.parameters.ru_config.serial_number} RMOD connection is: {self.rmod_info}"
            )
            return False
        self._generate_snapshot_and_extra_logs_names_and_paths(auto_snapshot, new_active_faults_ids)
        self._execute_debug_commands()
        check_output = self._execute_command(
            CCS_RUNNING_CHECK.format(ccs_ok=CCS_OK_MSG, ccs_nok_msg=CCS_FAILURE_MSG), as_rfsw=False
        )
        if CCS_OK_MSG in check_output.split("fi")[-1]:
            self._run_snapshot_command(timeout)
            if not self._confirm_file_exists_on_master_node(self.parameters.ram_snapshot_path):
                self.parameters.ram_snapshot_path = None
        else:
            self._handle_ccs_failure()
        if not self._confirm_file_exists_on_master_node(self.parameters.ram_extra_logs_path):
            self.parameters.ram_extra_logs_path = None
        return True

    def _run_snapshot_command(self, timeout: int):
        """
        Executes snapshot command on RMOD and confirms that success message is present in the output.
        Args:
            timeout (int): Time to wait for success message
        Returns:
            None
        """
        snapshot_cmd_output = self._execute_command(
            self._get_snapshot_command(), wait_time=timeout, write_output_to_logs=False, as_rfsw=False
        )
        if self.snapshot_succeed_msg not in snapshot_cmd_output:
            self.logger.debug("Snapshot collected success message not found in collecting output")

    def _handle_ccs_failure(self):
        """
        Handles CCS failure by executing commands to collect additional logs.
        Returns:
            None
        """
        self.logger.warning("CCS is not running. Additional logs will be collected instead of snapshot.")
        self.parameters.ram_snapshot_path = None
        for ccs_failure_cmd in CCS_FAILURE_COMMANDS:
            self._send_command(self._get_debug_command(ccs_failure_cmd), as_rfsw=False)

    def _execute_debug_commands(self):
        """
        Executes debug commands on RMOD and saves the output to the file.
        Returns:
            None
        """
        self.logger.info("Executing debug commands on RMOD")
        debug_commands_list = list(DEBUG_COMMANDS)
        if self.parameters.ru_config.radio_family in RMODS_5DOT1_FAMILY:
            debug_commands_list[-1] = SIMPLIFIED_PING_TOWER
        for debug_command in debug_commands_list:
            self._execute_command(
                self._get_debug_command(debug_command), write_output_to_logs=False, log_execution=False, as_rfsw=False
            )

    def _get_snapshot_command(self):
        """
        Generates snapshot command on RMOD and detects if serial console is connected to master or slave node.
        If slave node is detected, then command is wrapped by ssh tunel to the master node.
         Returns:
             str: snapshot command formatted with the snapshot file path
             and wrapped with ssh tunel to the master node if slave detected.
        """
        cmd = SNAPSHOT_CMD.format(snapshot_name=self.parameters.ram_snapshot_path)
        if not self.parameters.master_node:
            self.logger.warning("Board connected to the slave node. Snapshot may not be collected properly")
            cmd = MASTER_SSH_WRAPPER.format(cmd=cmd)
        return cmd

    def _get_debug_command(self, cmd):
        """
        Generates debug command on RMOD and detects if serial console is connected to master or slave node.
        If slave node is detected, then command is wrapped by ssh tunel to the master node.
         Returns:
             str: debug command or command wrapped with ssh tunel to the master node if slave detected.
        """
        cmd = f'{cmd} >> {self.parameters.ram_extra_logs_path} && echo ""'
        return cmd if self.parameters.master_node else MASTER_SSH_WRAPPER.format(cmd=cmd)

    def _move_snapshot_and_extra_logs_from_ram_to_rom(self):
        """Recreates snapshot directory in ROM and moves snapshot file and extra logs on RMOD.
        After that, confirms that snapshot file exists in the ROM of the master node.
        Returns:
           bool: True if snapshot file moved (may not be complete if no space on ROM),
               False if not moved for different reasons.
        """
        snap_dir = self.rom_snapshot_dir.split(self._rom)[-1]
        create_empty_rom_snap_dir_cmd = f"cd {self._rom} && rm -rf {snap_dir} && mkdir -p -m 755 {snap_dir}"
        create_empty_rom_snap_dir_cmd_on_node = (
            create_empty_rom_snap_dir_cmd
            if self.parameters.master_node
            else MASTER_SSH_WRAPPER.format(cmd=create_empty_rom_snap_dir_cmd)
        )
        self._send_command(create_empty_rom_snap_dir_cmd_on_node)
        snapshot_size = self._check_snapshot_size() if self.parameters.ram_snapshot_path else 0
        extra_logs_size = self._check_extra_logs_size() if self.parameters.ram_extra_logs_path else 0

        if snapshot_size and snapshot_size < self._check_mnt_runtime_space_available() * 0.9:
            self.logger.info(f"Moving snapshot file {self.parameters.ram_snapshot_path} to {self.rom_snapshot_dir}")
            snapshot_mv_cmd, ok_msg = self._get_move_snapshot_command()
            output = self._execute_command(snapshot_mv_cmd, wait_time=90, write_output_to_logs=True)
            if ok_msg in output.split('"')[-1]:
                self.logger.info(f"Snapshot file {self.parameters.ram_snapshot_path} moved to {self.rom_snapshot_dir}")

        if extra_logs_size and extra_logs_size < self._check_mnt_runtime_space_available() * 0.9:
            self.logger.info(f"Copying extra logs {self.parameters.ram_extra_logs_path} to {self.rom_snapshot_dir}")
            output, ok_msg = self._copy_extra_logs()
            out_cleared = output.split('"')[-1]
            if ok_msg in out_cleared and self._confirm_file_exists_on_master_node(self.parameters.rom_extra_logs_path):
                self.logger.info(f"Extra logs {self.parameters.ram_extra_logs_path} copied to {self.rom_snapshot_dir}")
        self._chmod_snapshot_and_logs_files()
        return self._confirm_file_exists_on_master_node(self.parameters.rom_snapshot_path)

    def _try_to_copy_snapshot_and_extra_logs_to_vm_from_ram(self, target_path_on_vm: str):
        """Tries to copy snapshot file and extra logs file from RMOD RAM to VM.
        Args:
            target_path_on_vm (str): Target directory to download a snapshot file.
        Returns:
            bool: True if snapshot file copied to VM, False otherwise.
        """
        snapshot_name = (
            self.parameters.ram_snapshot_path.split("/")[-1] if self.parameters.ram_snapshot_path else "Snapshot"
        )
        self.logger.warning(f"{snapshot_name} file is not moved for {self.parameters.ru_config.serial_number} to ROM!")
        self._setup_rmod_connection_network_params_for_snapshot_download()
        if self.parameters.ips_from_rmod is None:
            self.logger.error(
                f"Cannot get {self.parameters.ru_config.serial_number} RMOD IP. "
                "Moving snapshot to VM is not possible!"
            )
            return False
        self._try_to_determine_full_rack_smod()
        self.logger.info("Trying to copy logs from RMOD's RAM to VM")
        self._copy_snapshot_and_debug_file_from_rmod_to_vm(target_path_on_vm, snapshot_in_rom=False)
        return True

    def _check_mnt_runtime_space_available(self):
        """Checks available space on the ROM.
        Returns:
            int: The available space on the ROM in Megabytes.
        """
        mnt_runtime_space_cmd = 'echo -n "MNTSIZE:" && df -k /mnt/runtime | awk "NR==2 {print \\$4}"'
        mnt_runtime_space_cmd = (
            mnt_runtime_space_cmd
            if self.parameters.master_node
            else MASTER_SSH_WRAPPER.format(cmd=mnt_runtime_space_cmd)
        )
        max_retries = 3
        size = 0
        for _ in range(max_retries):
            mnt_runtime_space = self._execute_command(mnt_runtime_space_cmd)
            match = re.search(r"MNTSIZE:(\d+)", mnt_runtime_space)
            if match:
                size = int(match.group(1))
                self.logger.info(f"Available /mnt/runtime space: {size}KB")
                break
            else:
                self.logger.debug(f"Problem with getting mnt runtime space size from output: {mnt_runtime_space}")
                time.sleep(1)
        else:
            self.logger.error("Failed to get mnt runtime space size after 3 attempts")
        return size

    def _check_snapshot_size(self):
        """Checks snapshot file size before moving it to ROM (for RMOD safety).
        Returns:
            int: The size of the snapshot file in Megabytes.
        """
        snapshot_size_cmd = f'echo -n "SNAPSIZE:" && du -k {self.parameters.ram_snapshot_path}'
        snapshot_size_cmd = (
            snapshot_size_cmd if self.parameters.master_node else MASTER_SSH_WRAPPER.format(cmd=snapshot_size_cmd)
        )
        max_retries = 3
        size = 9999  # Default huge value to skip moving file
        for _ in range(max_retries):
            snapshot_size = self._execute_command(snapshot_size_cmd)
            match = re.search(r"SNAPSIZE:(\d+)", snapshot_size)
            if match:
                size = int(match.group(1))
                self.logger.info(f"Snapshot size: {size}KB")
                break
            elif "No such file" in snapshot_size:
                self.logger.warning(f"Snapshot file {self.parameters.ram_snapshot_path} not found")
                self.parameters.ram_snapshot_path = None
                return 0
            else:
                self.logger.debug(f"Problem with getting snapshot size from output: {snapshot_size}")
                time.sleep(1)
        else:
            self.logger.error(f"Failed to get snapshot size after {max_retries} attempts")
        return size

    def _check_extra_logs_size(self):
        """Checks extra logs file size before moving it to ROM (for RMOD safety).
        Returns:
            int: The size of the extra logs file in Megabytes.
        """
        extra_logs_size_cmd = f"echo -n 'EXTRALOGSIZE:' && du -k {self.parameters.ram_extra_logs_path}"
        extra_logs_size_cmd = (
            extra_logs_size_cmd if self.parameters.master_node else MASTER_SSH_WRAPPER.format(cmd=extra_logs_size_cmd)
        )
        max_retries = 3
        size = 9999  # Default huge value to skip moving file
        for _ in range(max_retries):
            extra_logs_size = self._execute_command(extra_logs_size_cmd)
            match = re.search(r"EXTRALOGSIZE:(\d+)", extra_logs_size)
            if match:
                size = int(match.group(1))
                self.logger.info(f"Extra logs size: {size}KB")
                break
            elif "No such file" in extra_logs_size:
                self.logger.warning(f"Extra logs file {self.parameters.ram_extra_logs_path} not found")
                self.parameters.ram_extra_logs_path = None
                return 0
            else:
                self.logger.debug(f"Problem with getting extra logs size from output: {extra_logs_size}")
                time.sleep(1)
        else:
            self.logger.error(f"Failed to get extra logs size after {max_retries} attempts")
        return size

    def _copy_extra_logs(self):
        """Copies extra debug logs file to rom.
        Returns:
           tuple: (str, str) where first string is the command execution output and the second is the success message
            used in the command to be found in output.
        """
        cp_cmd, ok_msg = self._get_copy_extra_logs_command()
        output = self._execute_command(cp_cmd, wait_time=90, write_output_to_logs=True)
        return output, ok_msg

    def _get_copy_extra_logs_command(self):
        """Generates the command to copy extra debug logs from the RAM to the ROM on the RMOD.
        If the RMOD is connected to the master node, the command is returned directly.
        If the RMOD is connected to a slave node, the command is wrapped with an SSH tunnel to the master node.
        Returns:
            tuple: (str, str) where the first string is the formatted command to copy extra logs,
                   and the second string is the success message used in the command to be found in output.
        """
        ok_msg = "Extra logs copied"
        copy_extra_logs_file_cmd = (
            f"sudo cp {self.parameters.ram_extra_logs_path} "
            f'{self.parameters.rom_extra_logs_path} && echo "{ok_msg}"'
        )
        copying_extra_logs_cmd = (
            copy_extra_logs_file_cmd
            if self.parameters.master_node
            else MASTER_SSH_WRAPPER.format(cmd=copy_extra_logs_file_cmd)
        )
        return copying_extra_logs_cmd, ok_msg

    def _get_move_snapshot_command(self):
        """Generates the command to move a snapshot file from the RAM to the ROM on the RMOD.
        This method constructs a command that first creates an empty snapshot directory in the ROM
        and then moves the snapshot file from its location in the RAM to the ROM. If the RMOD is
        connected to a slave node, the command is wrapped with an SSH tunnel to the master node.
        Returns:
            tuple: (str, str) where the first string is the formatted command to move the snapshot file,
                   and the second string is the success message used in the command to be found in output.
        """
        ok_msg = "Snapshot moved"
        move_snap_file_cmd = (
            f"sudo mv {self.parameters.ram_snapshot_path} "
            f"{self.parameters.rom_snapshot_path} "
            f'&& echo "{ok_msg}"'
        )
        move_snap_file_cmd = (
            move_snap_file_cmd if self.parameters.master_node else MASTER_SSH_WRAPPER.format(cmd=move_snap_file_cmd)
        )
        return move_snap_file_cmd, ok_msg

    def _chmod_snapshot_and_logs_files(self):
        """Changes permissions for snapshot and extra logs files in ROM to be readable and writable for all users.
        Returns:
            None
        """
        chmod_cmd = f"sudo chmod 644 {self.parameters.rom_snapshot_path} {self.parameters.rom_extra_logs_path}"
        chmod_cmd = chmod_cmd if self.parameters.master_node else MASTER_SSH_WRAPPER.format(cmd=chmod_cmd)
        self._send_command(chmod_cmd, as_rfsw=False)

    def _generate_snapshot_and_extra_logs_names_and_paths(
        self, auto_snapshot: bool = False, new_active_faults_ids: list = None
    ):
        """Fills the necessary snapshot and extra logs names with the current timestamp and creates paths.
        Args:
            auto_snapshot (bool): True if snapshot is taken automatically, False if manually.
            new_active_faults_ids (list): List of new active faults IDs that triggered the auto snapshot.
         Returns:
            None
        """
        logs_differentiator = f"{self.parameters.log_prefix}_" f"{datetime.datetime.now().strftime(self.tstamp_format)}"
        if auto_snapshot:
            fids = "_".join(new_active_faults_ids)
            self.parameters.snapshot_name = f"AutoSnapshot_FIDs_{fids}_{logs_differentiator}.zip"
            self.parameters.extra_logs_name = f"Debug_FIDs_{fids}_{logs_differentiator}.log"
            self.rom_snapshot_dir = self._rom + self._rom_auto_snapshot_dir
        else:
            self.parameters.snapshot_name = f"Snapshot_{logs_differentiator}.zip"
            self.parameters.extra_logs_name = f"Debug_{logs_differentiator}.log"
            self.rom_snapshot_dir = self._rom + self._rom_user_snapshot_dir
        self.parameters.ram_snapshot_path = f"/ram/{self.parameters.snapshot_name}"
        self.parameters.rom_snapshot_path = f"{self.rom_snapshot_dir}{self.parameters.snapshot_name}"
        self.parameters.ram_extra_logs_path = f"/ram/{self.parameters.extra_logs_name}"
        self.parameters.rom_extra_logs_path = f"{self.rom_snapshot_dir}{self.parameters.extra_logs_name}"
        self.user_snapshot_and_debug_files_for_download.add(
            (self.parameters.rom_snapshot_path, self.parameters.rom_extra_logs_path)
        )

    def _confirm_file_exists_on_master_node(self, filepath: str):
        """Confirms that expected file exists under given filepath.
        Args:
            filepath (str): path to the file on the master node.
        Returns:
            bool: True if file exists on master node, False otherwise.
        """
        if filepath is None:
            self.logger.info("File path is None, cannot confirm file existence.")
            return False
        ls_cmd = f"ls {filepath}"
        ls_cmd = ls_cmd if self.parameters.master_node else MASTER_SSH_WRAPPER.format(cmd=ls_cmd)
        if "No such file" not in self._execute_command(ls_cmd):
            self.logger.info(f"File {filepath} exists on master RMOD node")
            return True
        self.logger.info(f"File {filepath} not exists on RMOD {self.parameters.ru_config.serial_number} master node")
        return False

    def _set_rmod_credentials(self, password, username):
        """Sets RMOD credentials for SSH handler.
        Args:
            password (str): RMOD password.
            username (str): RMOD username.
        Returns:
            None
        """
        self.parameters.ru_config.password = password
        self.parameters.ru_config.username = username
        self._rsi.set_rmod_credentials(login=username, password=password, alias=self.alias)

    def _set_proxy_vm_address_and_username(self, proxy_vm_address: str, proxy_vm_username: str):
        """Sets proxy VM address and username for SSH handler.
        Args:
            proxy_vm_address (str): Proxy VM address.
            proxy_vm_username (str): Proxy VM username.
        Returns:
            None
        """
        self.parameters.ru_config.proxy_vm_credentials = {"ip": proxy_vm_address, "username": proxy_vm_username}

    def _setup_rmod_connection_network_params_for_snapshot_download(self):
        """Fills the necessary snapshot download network parameters.
        Returns:
           None
        """
        self.logger.debug("Invoke SSH Handler to SMOD")
        self.ssh_handler = InvokeSshHandler(logger=self.logger, proxy_vm=self.parameters.ru_config.proxy_vm_credentials)
        self._try_to_determine_rmod_ip()

    def _copy_snapshot_and_debug_file_from_rmod_to_vm(self, target_path: str = None, snapshot_in_rom: bool = True):
        """Copies snapshot and debug file from RMOD to SMOD and then to VM using InvokeSshHandler package.
        Args:
            target_path (str): Path to save snapshot on VM.
                Defaults to default log path where this library logs are stored set with this class init.
            snapshot_in_rom: True if snapshot is in ROM, False if in RAM.
        Returns:
            None
        """
        extra_logs_name, extra_log_dir, snap_name, snap_dir = self._get_snap_dir_and_log_names(snapshot_in_rom)
        smod_snap_dir = "~/"
        bts_mode = f"{'slave' if self.parameters.slave_bts else 'master'}"
        try:
            if snap_name is not None:
                self._transfer_file_from_rmod_to_vm(
                    bts_mode=bts_mode,
                    smod_snap_dir=smod_snap_dir,
                    logs_dir=snap_dir,
                    logs_name=snap_name,
                    target_path=target_path,
                )
            if extra_logs_name is not None:
                self._transfer_file_from_rmod_to_vm(
                    bts_mode=bts_mode,
                    smod_snap_dir=smod_snap_dir,
                    logs_dir=extra_log_dir,
                    logs_name=extra_logs_name,
                    target_path=target_path,
                )
        except Exception as invoke_shell_exception:
            self.logger.error(
                f"Moving {self.parameters.ru_config.serial_number} snapshot and extra logs "
                f"from RMOD via {bts_mode} SMOD to VM failed with: {invoke_shell_exception}"
            )
            return
        if snapshot_in_rom and self.parameters.rom_snapshot_path:
            snap_in_dir = self.parameters.rom_snapshot_path.split(self._rom)[-1]
            self.logger.info("Removing snapshot file from ROM after copying to VM")
            self._send_command(f"cd {self._rom} && rm -rf {snap_in_dir}")

    def _transfer_file_from_rmod_to_vm(
        self, bts_mode: str, smod_snap_dir: str, logs_dir: str, logs_name: str, target_path: str
    ):
        """Transfers a log file from the RMOD to the VM.
        This method first transfers the file from the RMOD to the SMOD and then transfers it from the SMOD to the VM.
        Args:
            bts_mode (str): The mode of the BTS (e.g., 'master' or 'slave').
            smod_snap_dir (str): The directory on the SMOD where the snapshot is stored.
            logs_dir (str): The directory on the RMOD where the log file is located.
            logs_name (str): The name of the log file to be transferred.
            target_path (str): The target path on the VM where the log file will be saved.
        Returns:
            None
        """
        self._transfer_log_file_from_rmod_to_smod(
            bts_mode=bts_mode, logs_name=logs_name, smod_snap_dir=smod_snap_dir, logs_dir=logs_dir
        )
        self._transfer_log_file_from_smod_to_vm(
            bts_mode=bts_mode, logs_name=logs_name, smod_snap_dir=smod_snap_dir, target_path=target_path
        )

    def _transfer_log_file_from_rmod_to_smod(self, bts_mode: str, logs_name: str, smod_snap_dir: str, logs_dir: str):
        """Transfers a log file from the RMOD to the SMOD.
        This method copies the specified log file from the RMOD to the SMOD using the SSH handler.
        Args:
            bts_mode (str): The mode of the BTS (e.g., 'master' or 'slave').
            logs_name (str): The name of the log file to be transferred.
            smod_snap_dir (str): The directory on the SMOD where the log file will be stored.
            logs_dir (str): The directory on the RMOD where the log file is located.
        Returns:
            None
        """
        self.logger.debug(f"Trying to copy {logs_name} logs from RMOD to {bts_mode} SMOD")
        self.ssh_handler.connect_to_fhnet(slave_bts=self.parameters.slave_bts)
        self.ssh_handler.get_file_from_rmod_to_smod(
            filename=logs_name,
            smod_path=smod_snap_dir,
            rmod_path=logs_dir,
            rmod_ip=self.parameters.ip_from_smod,
            username=self.parameters.ru_config.username,
            password=self.parameters.ru_config.password,
        )

    def _transfer_log_file_from_smod_to_vm(self, bts_mode: str, logs_name: str, smod_snap_dir: str, target_path: str):
        """Transfers a log file from the SMOD to the VM.
        This method first ensures the target directory exists on the VM. If the directory cannot be created,
        it falls back to the default log directory. Then, it downloads the specified log file from the SMOD
        to the VM and removes the file from the SMOD after the transfer is complete.
        Args:
            bts_mode (str): The mode of the BTS (e.g., 'master' or 'slave').
            logs_name (str): The name of the log file to be transferred.
            smod_snap_dir (str): The directory on the SMOD where the log file is stored.
            target_path (str): The target directory on the VM where the log file will be saved. If None, the
                               default log directory is used.
        Returns:
            None
        """
        if not target_path:
            target_path = self.parameters.log_dir
        else:
            try:
                os.makedirs(target_path, exist_ok=True)
            except OSError as e:
                default_target_path = self.parameters.log_dir
                self.logger.error(
                    f"Creating of {target_path} has failed with: {e}. {logs_name} will be"
                    f" downloaded to {default_target_path}"
                )
                target_path = default_target_path
        self.logger.debug(f"Trying to copy {logs_name} from {bts_mode} SMOD to VM")
        self.ssh_handler.download_file_from_smod_to_vm(
            filename=logs_name, smod_path=smod_snap_dir, local_path=target_path, slave_bts=self.parameters.slave_bts
        )
        self._remove_files_from_smod(smod_snap_dir, logs_name)
        self.logger.info(f"{logs_name} file have been successfully collected and moved to VM.")

    def _get_snap_dir_and_log_names(self, snapshot_in_rom: bool):
        """Retrieves the directory paths and file names for snapshot and extra debug logs.
        Args:
            snapshot_in_rom (bool): Indicates whether the snapshot is stored in ROM (True) or RAM (False).
        Returns:
            tuple: A tuple containing:
                - extra_logs_name (str or None): The name of the extra debug logs file.
                - extra_logs_dir (str or None): The directory path of the extra debug logs file.
                - snapshot_name (str or None): The name of the snapshot file.
                - snapshot_dir (str or None): The directory path of the snapshot file.
        """
        extra_logs_name, extra_logs_dir, snapshot_dir, snapshot_name = None, None, None, None
        if snapshot_in_rom and self.parameters.rom_snapshot_path:
            snapshot_dir, snapshot_name = os.path.split(self.parameters.rom_snapshot_path)
        elif not snapshot_in_rom and self.parameters.ram_snapshot_path is not None:
            snapshot_dir, snapshot_name = os.path.split(self.parameters.ram_snapshot_path)
        if self._confirm_file_exists_on_master_node(self.parameters.rom_extra_logs_path):
            extra_logs_dir, extra_logs_name = os.path.split(self.parameters.rom_extra_logs_path)
        elif self.parameters.ram_extra_logs_path:
            self.parameters.rom_extra_logs_path = None
            extra_logs_dir, extra_logs_name = os.path.split(self.parameters.ram_extra_logs_path)
        self.logger.debug(
            f"Retrieved snapshot directory: {snapshot_dir}, "
            f"snapshot name: {snapshot_name}, "
            f"extra logs directory: {extra_logs_dir}, "
            f"extra logs name: {extra_logs_name}"
        )
        return extra_logs_name, extra_logs_dir, snapshot_name, snapshot_dir

    def _remove_files_from_smod(self, smod_snap_dir: str, file_name: str):
        """Removes snapshot or extra files from SMOD(s) after copying to VM. If slave BTS is used,
           then it removes the file from slave BTS as well.
        Args:
            smod_snap_dir (str): Path to the snapshot directory on SMOD.
            file_name (str): Name of a snapshot or a debug file.
        Returns:
            None
        """
        self.logger.debug(f"{file_name} has been copied to VM. Removing it from SMOD(s).")
        if self.parameters.slave_bts:
            self.ssh_handler.send_command_and_return_output(
                f"rm {smod_snap_dir}{file_name}", slave_bts=True, expected_phrase="root@"
            )
        smod_snap_dir = "/ram/" if self.parameters.slave_bts else smod_snap_dir
        self.ssh_handler.send_command_and_return_output(
            f"rm {smod_snap_dir}{file_name}", slave_bts=False, expected_phrase="root@"
        )

    def _try_to_determine_full_rack_smod(self):
        """Uses RMOD's IP to determine SMOD master and slave nodes.
        Returns:
            None
        """
        master_ping_ok = self._ping_rmod_from_smod(slave_bts=False)
        if master_ping_ok:
            self.parameters.slave_bts = False
        elif master_ping_ok is not None:
            slave_pinged = self._ping_rmod_from_smod(slave_bts=True)
            if slave_pinged:
                self.parameters.slave_bts = True
            else:
                self.logger.warning(
                    f"RMOD IP(s) {self.parameters.ips_from_rmod} not reachable from SMOD. "
                    f"Please check the connection"
                )
        else:
            self.logger.error("Cannot determine SMOD master/slave nodes due to connection issue with BTS.")

    def _ping_rmod_from_smod(self, slave_bts: bool):
        """Pings RMOD from SMOD master/slave to check if the connection is established.
        Args:
            slave_bts (bool): True if pinging from slave BTS, False otherwise.
        Returns:
            bool | None: True if ping successful, False otherwise. None if connection to BTS failed.
        """
        bts_mode = "slave" if slave_bts else "master"
        try:
            self.ssh_handler.connect_to_fhnet(slave_bts=slave_bts)
        except (BTSConnectionError, InvalidSourceBtsError, ExpectedPhraseNotFoundError) as e:
            self.logger.error(f"Cannot ping RMOD IP from {bts_mode} BTS: {e}")
            return None
        for rmod_ip in self.parameters.ips_from_rmod:
            ping_output = self.ssh_handler.send_command_and_return_output(
                PING_CMD.format(ip=rmod_ip), slave_bts=slave_bts, expected_phrase="root@FHNET"
            )
            if PING_LOSS not in ping_output and NETWORK_UNREACHABLE not in ping_output:
                self.parameters.ip_from_smod = rmod_ip
                self.logger.info(f"Successfully pinged RMOD IP {rmod_ip} from {bts_mode} BTS")
                return True
        return False
